entries[57761] = { ["name"] = "Hirnfrost", ["text"] = "100 Meter Reichweite\nSofort\nEuer zuletzt gewirkter Zauber 'Netherorkan', 'Lebende Bombe' oder 'Frostbombe' hat eine Chance, den Effekt 'Hirnfrost' auzulösen, wenn er Schaden verursacht.\n\nDer Effekt 'Hirnfrost' bewirkt 15 Sek. lang, dass Euer nächstes Wirken von 'Frostfeuerblitz' ein kostenloser Spontanzauber ist und auf das Ziel wirkt, als wäre es eingefroren." }
