entries[57765] = { ["name"] = "Pflege", ["text"] = "22% von Grundmana 40 Meter Reichweite\nWirken in 1.5 sek.\nHeilt ein freundliches Ziel um 694 bis 806. Ist ein durch Euch gewirkter Effekt von 'Verjüngung', 'Nachwachsen' oder 'Blühendes Leben' auf dem Ziel aktiv, erhöht sich die Heilung um zusätzliche 20%." }
