entries[57767] = { ["name"] = "Läuterung", ["text"] = "30 Meter Reichweite\nSofort\nReinigt ein verbündetes Ziel und hebt dabei 1 Gifteffekt, 1 Krankheitseffekt und 1 Magieeffekt auf." }
entries[57768] = { ["name"] = "Gemüseeintopf", ["text"] = "Wirken in 2 sek.\nReagenzien:\nKühles Fleisch (4), Kristallsangkarotte (4)\nKocht 4 Stück kühles Fleisch und 4 Kristallsangkarotten über einem Feuer, um Gemüseeintopf herzustellen." }
entries[57769] = { ["name"] = "Siegel des Befehls", ["text"] = "14% von Grundmana\nSofort\nVerleiht dem Paladin eine Chance, 70 zusätzlichen Heiligschaden zu verursachen. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein. Hält 2 Min. lang an.\n(1s Abklingzeit)" }
