entries[57774] = { ["name"] = "Richturteil des Lichts", ["text"] = "5% von Grundmana 10 Meter Reichweite\nSofort\nEntfesselt bis Abbruch lang die Energie eines Siegelzaubers um einen Feind zu richten, wodurch Nahkampfangriffen auf das gerichtete Ziel eine Chance gewährt wird, beim Angreifer Gesundheit wiederherzustellen." }
