entries[57790] = { ["name"] = "Blutdurst", ["text"] = "Nahkampfreichweite\nSofort\nGreift das Ziel sofort an und verursacht (Angriffskraft * 142 / 100) Schaden. Zusätzlich werden die nächsten erfolgreichen 0 Nahkampfangriffe 1,5% der maximalen Gesundheit wiederherstellen. Dieser Effekt hält bis Abbruch lang an. Schaden basiert auf Angriffskraft." }
entries[57791] = { ["name"] = "Blutdurst", ["text"] = "Sofort\nGreift das Ziel sofort an und verursacht 30 Schaden. Zusätzlich werden die nächsten erfolgreichen 5 Nahkampfangriffe 1,5% der maximalen Gesundheit wiederherstellen. Dieser Effekt hält 8 Sek. lang an." }
