entries[57793] = { ["name"] = "Heldenhafter Sprung", ["text"] = "8 - 25 Meter Reichweite\nSofort 45 sek. Abklingzeit\nSpringt durch die Luft und schmettert auf alle Feinde im Umkreis von 8 Metern um das Zielgebiet hinab, verursacht 1% Waffenschaden und betäubt sie 0.10 Sek. lang." }
