entries[57795] = { ["name"] = "Verwüsten", ["text"] = "Nahkampfreichweite\nSofort\nZerreißt die Rüstung des Ziels und ruft den Effekt 'Rüstung zerreißen' hervor. Zusätzlich werden für jeden auf das Ziel wirkenden Effekt von 'Rüstung zerreißen' 20% Waffenschaden plus 50 verursacht. 'Rüstung zerreißen' ist bis zu 5-mal stapelbar." }
