entries[58286] = { ["name"] = "Glyphe 'Wassergestalt'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nGeringe Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht Euer Schwimmtempo in Wassergestalt um 50%." }
entries[58287] = { ["name"] = "Glyphe 'Chamäleon'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nGeringe Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nJedes Mal, wenn Ihr Katzen- oder Bärengestalt annehmt, werdet Ihr in verwandelter Gestalt eine andere Fellfarbe haben." }
entries[58288] = { ["name"] = "Glyphe 'Blüte'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Endheilung von 'Blühendes Leben' um 50%, verringert aber die Dauer um 5 Sek. und Eure Zauber 'Heilende Berührung', 'Pflege' und 'Nachwachsen' setzen die Dauer nicht mehr zurück." }
entries[58289] = { ["name"] = "Glyphe 'Anmut'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nGeringe Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Katzenhafte Anmut' verringert Fallschaden, selbst wenn Ihr Euch nicht in Katzengestalt befindet." }
