entries[58296] = { ["name"] = "Glyphe 'Freund des Waldes'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nGeringe Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nLehrt Euch die Fähigkeit 'Freund des Waldes'.\n\nDadurch kann der Druide Freundschaft mit einem Umgebungstier schließen, das ihm anschließend 1 Stunde lang folgt." }
entries[58297] = { ["name"] = "Glyphe 'Aspekt des Rudels'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\nGeringe Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Reichweite Eurer Fähigkeit 'Aspekt des Rudels' um 15 Meter." }
entries[58298] = { ["name"] = "Glyphe 'Stampede'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nGeringe Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\n'Stampede' ruft keine Begleiter aus Eurem Stall mehr herbei, sondern verwendet stattdessen Kopien Eures aktuellen Begleiters." }
entries[58299] = { ["name"] = "Glyphe 'Tier wiederbeleben'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nGeringe Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Dauer der durch erlittenen Schaden verursachten Zauberzeiterhöhung beim Anwenden Eurer Fähigkeit 'Tier wiederbeleben' um 100%." }
entries[58301] = { ["name"] = "Glyphe 'Kleinere Proportionen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nGeringe Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Größe Eures Tiers ein wenig." }
entries[58302] = { ["name"] = "Glyphe 'Feuerwerk'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nGeringe Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nLehrt Euch die Fähigkeit 'Feuerwerk'.\n\nSchießt Feuerwerk von Eurem Gewehr, Bogen oder Eurer Armbrust ab." }
entries[58303] = { ["name"] = "Glyphe 'Stachelschwein'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nGeringe Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Verwandlung' verwandelt das Ziel in ein Stachelschwein, anstatt in ein Schaf." }
