entries[58307] = { ["name"] = "Glyphe 'Affe'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nGeringe Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Verwandlung' verwandelt das Ziel in einen Affen, anstatt in ein Schaf." }
