entries[58310] = { ["name"] = "Glyphe 'Pinguin'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nGeringe Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Verwandlung' verwandelt das Ziel in einen Pinguin, anstatt in ein Schaf." }
entries[58311] = { ["name"] = "Glyphe 'Nachsinnen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nGeringe Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nLehrt Euch die Fähigkeit 'Nachsinnen'.\n\nGestattet Euch einen kurzen Moment des Friedens, den Ihr in stiller Kontemplation des Lichts verbringt." }
entries[58312] = { ["name"] = "Glyphe 'Schwingen der Vergeltung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nGeringe Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Zornige Vergeltung' stellt vier Schwingen dar." }
entries[58313] = { ["name"] = "Glyphe 'Lichtblitz'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nErhebliche Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr 'Lichtblitz' auf ein Ziel wirkt, wird Eure nächste innerhalb von 7 Sek. auf dieses Ziel gewirkte Heilung um 10% erhöht." }
