entries[58315] = { ["name"] = "Glyphe 'Siegel des Blutes'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nGeringe Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Siegel der Wahrheit' nutzt die Animation von 'Siegel des Blutes'." }
