entries[58318] = { ["name"] = "Glyphe 'Zeit schinden'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nGeringe Glyphe\nKlassen: Priester\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Effekt 'Zeit schinden' hat nun einen visuellen Effekt." }
entries[58319] = { ["name"] = "Glyphe 'Levitieren'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nErhebliche Glyphe\nKlassen: Priester\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht Euer Bewegungstempo während des Levitierens sowie bis zu 10 Sek. danach um 15%." }
entries[58320] = { ["name"] = "Glyphe 'Untote fesseln'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nGeringe Glyphe\nKlassen: Priester\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nÄndert das Aussehen Eures Zaubers 'Untote fesseln'." }
entries[58321] = { ["name"] = "Glyphe 'Reflektierender Schild'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nErhebliche Glyphe\nKlassen: Priester\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\n70% des Schadens, den Ihr durch 'Machtwort: Schild' absorbiert, werden auf den Angreifer zurückgeworfen. Dieser Schaden verursacht keine Bedrohung." }
