entries[58325] = { ["name"] = "Glyphe 'Schloss knacken'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nGeringe Glyphe\nKlassen: Schurke\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Kanalisierungsdauer Eurer Fähigkeit 'Schloss knacken' um 100%." }
entries[58326] = { ["name"] = "Glyphe 'Taschendiebstahl'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nGeringe Glyphe\nKlassen: Schurke\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Reichweite Eurer Fähigkeit 'Taschendiebstahl' um 5 Meter." }
entries[58327] = { ["name"] = "Glyphe 'Sicheres Fallen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\nGeringe Glyphe\nKlassen: Schurke\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Sicheres Fallen' ermöglicht es Euch, noch tiefer zu fallen, ohne Schaden zu erleiden." }
entries[58328] = { ["name"] = "Glyphe 'Gifte'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nGeringe Glyphe\nKlassen: Schurke\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr streicht Eure Waffen 50% schneller mit Giften ein." }
entries[58329] = { ["name"] = "Glyphe 'Astraler Rückruf'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nGeringe Glyphe\nKlassen: Schamane\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Abklingzeit Eures Zaubers 'Astraler Rückruf' um 5 Min." }
entries[58330] = { ["name"] = "Glyphe 'Fernsicht'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nGeringe Glyphe\nKlassen: Schamane\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Fernsicht' kann auch in Räumen und Gebäuden eingesetzt werden." }
entries[58331] = { ["name"] = "Glyphe 'Heilender Sturm'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nErhebliche Glyphe\nKlassen: Schamane\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nJede Aufladung von 'Waffe des Mahlstroms' erhöht auch Eure hervorgerufene direkte Heilung um 20%." }
entries[58332] = { ["name"] = "Glyphe 'Spektralwolf'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nGeringe Glyphe\nKlassen: Schamane\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nÄndert das Erscheinungsbild Eurer Geisterwolfgestalt ab, in der Ihr daraufhin als Spektralwolf erscheint." }
entries[58333] = { ["name"] = "Glyphe 'Totemische Einkreisung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nGeringe Glyphe\nKlassen: Schamane\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr einen Totemzauber wirkt, werden ebenfalls unaufgeladene Totems aller aktuell ungenutzten Elemente platziert. Diese Totems verfügen über 5 Gesundheit und rufen keine anderen Effekte hervor." }
