entries[58339] = { ["name"] = "Glyphe 'Dämon unterwerfen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nGeringe Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Zauberzeit Eures Zaubers 'Dämon unterwerfen' um 50%." }
entries[58340] = { ["name"] = "Glyphe 'Auge von Kilrogg'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nGeringe Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Auge von Kilrogg ist nicht mehr verstohlen, kann jedoch den Beschwörungskreis Eures dämonischen Zirkels platzieren. Der Hexenmeister muss sich in der Sichtlinie des Auges von Kilrogg befinden, um den dämonischen Zirkel zu platzieren.\n\nZusätzlich wird das Bewegungstempo des Auges von Kilrogg um 50% erhöht und ihm wird in Gegenden, wo die Nutzung von fliegenden Reittieren möglich ist, Flugfähigkeit verliehen." }
