entries[58342] = { ["name"] = "Glyphe 'Mystischer Ruf'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nGeringe Glyphe\nKlassen: Krieger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeiten 'Schlachtruf' und 'Befehlsruf' bewirken, dass Ihr 1 Sek. lang in der Luft schwebt." }
